<div class="details-panel product-details"><p class="eyebrow">OFFICIAL COLLECTION</p><h2><?=e($d['name'])?></h2><p class="product-price" id="variant-price"><?=$chosen?e(Money::format((int)$chosen['price_cents'])):'Unavailable'?> <small>USD</small></p><div class="prose"><?=PublicSite::text($d['description'])?></div>
<?php if($chosen):?><form method="post" action="<?=e(app_url('shop/cart.php'))?>" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="nonce" value="<?=e(bin2hex(random_bytes(32)))?>"><label>Color / size<select name="variant_id" id="product-variant"><?php foreach($variants as $v):?><option value="<?=$v['id']?>" data-price="<?=e(Money::format((int)$v['price_cents']))?>" data-stock="<?=$v['stock']?>" <?=$chosen['id']===$v['id']?'selected':''?>><?=e(Catalog::label($v).' — '.Money::format((int)$v['price_cents']).((int)$v['stock']===0?' — Out of stock':''))?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" max="20" value="1" required></label><p id="variant-stock" role="status"><?=(int)$chosen['stock']>0?'In stock':'Out of stock'?></p><button id="product-add" type="submit" class="button wide" <?=(int)$chosen['stock']===0?'disabled':''?>>Add to bag</button></form><?php else:?><p>No active variants are available.</p><?php endif;?>
