<?php else:?><div class="cart-layout"><div class="cart-lines"><?php foreach($bag['items'] as $line):$p=$line['product'];?><article class="cart-line"><div class="cart-art"><?=$p?PublicSite::image((int)($p['data']['image_ids'][0]??0),$p['data']['name']):'<span>Unavailable</span>'?></div><div><h2><?=$p?e($p['data']['name']):'Item no longer available'?></h2><p><?=e($line['label'])?></p><?php if($line['issue']):?><p class="stock-problem" role="status"><?=e($line['issue'])?></p><?php else:?><p><?=e(Money::format($line['price']))?> each · <?=e(Money::format($line['total']))?></p><?php endif;?><form method="post" action="<?=e(app_url('shop/cart.php'))?>" class="cart-edit"><?=csrf_field()?><input type="hidden" name="action" value="set"><input type="hidden" name="nonce" value="<?=e(bin2hex(random_bytes(32)))?>"><input type="hidden" name="variant_id" value="<?=$line['variant_id']?>"><label>Quantity<input type="number" name="quantity" min="0" max="20" value="<?=$line['quantity']?>" required></label><button type="submit" class="button secondary">Update</button><small>Use 0 to remove.</small></form></div></article><?php endforeach;?></div><aside class="details-panel cart-summary"><p class="eyebrow">YOUR BAG</p><h2>Order summary</h2><div class="summary-total"><span>Available-item subtotal</span><strong><?=e(Money::format($bag['subtotal']))?></strong></div><?php if($bag['problems']):?><p class="stock-problem">Unavailable quantities are excluded. Update or remove those items.</p><?php endif;?><p class="small muted">Prices and availability are refreshed from the catalog. Items are not reserved. Shipping and tax are not calculated yet.</p><div class="store-notice"><strong>Checkout is not open yet.</strong><p>No payment details are requested and no order has been placed.</p></div><a class="button secondary wide" href="<?=e(app_url('shop/'))?>">Continue browsing</a></aside></div><?php endif;endif;?>
